<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetTemplateVO;
use Civi\Lughauth\Features\Document\Template\Domain\TemplateRef;

trait TemplateAssetTemplateAccessor
{
    private TemplateAssetTemplateVO $_template;
    public function getTemplate(): TemplateRef
    {
        return $this->_template->value();
    }
    public function template(): TemplateAssetTemplateVO
    {
        return $this->_template;
    }
    public function isTemplateChanged(?self $original = null): bool
    {
        return !$this->_template->equals($original?->_template);
    }
    public function withTemplate(TemplateAssetTemplateVO|TemplateRef $template): self
    {
        $copy = clone $this;
        $copy->_template = TemplateAssetTemplateVO::from($template);
        return $copy;
    }
}
